package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TypeFactory.constructType(Type type, Class<?> contextClass).
 * This method is a convenience wrapper that resolves the context class into a JavaType 
 * and then constructs the target type.
 */
public class TypeFactory_constructType_TriageGen1Test {

    @Test
    public void testConstructType_SimpleClass() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();
        Type type = String.class;
        Class<?> contextClass = Integer.class;

        JavaType result = typeFactory.constructType(type, contextClass);

        Assert.assertNotNull(result);
        Assert.assertEquals(String.class, result.getRawClass());
    }

    @Test
    public void testConstructType_ParameterizedType() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Representing List<String>
        ParameterizedType type = new ParameterizedTypeImpl(List.class, new Type[]{String.class});
        Class<?> contextClass = HashMap.class;

        JavaType result = typeFactory.constructType(type, contextClass);

        Assert.assertNotNull(result);
        Assert.assertEquals(List.class, result.getRawClass());
        Assert.assertEquals(1, result.getTypeParameters().length);
        Assert.assertEquals(String.class, result.getTypeParameters()[0].getRawClass());
    }

    @Test
    public void testConstructType_WithContextAsGenericType() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // Target: Map<String, ?>
        // Context: Map<Integer, Integer>
        // Even though context is provided as a Class, the internal logic converts 
        // contextClass -> constructType(contextClass) -> JavaType.

        Type type = typeFactory.constructType(Map.class); // Map without params
        Class<?> contextClass = Map.class;

        JavaType result = typeFactory.constructType(type, contextClass);

        Assert.assertNotNull(result);
        Assert.assertEquals(Map.class, result.getRawClass());
    }

    @Test
    public void testConstructType_ArrayType() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        Type type = String[].class;
        Class<?> contextClass = Object.class;

        JavaType result = typeFactory.constructType(type, contextClass);

        Assert.assertNotNull(result);
        Assert.assertTrue(result.isArrayType());
        Assert.assertEquals(String.class, result.getElementType().getRawClass());
    }

    @Test
    public void testConstructType_WildcardType() {
        TypeFactory typeFactory = TypeFactory.defaultInstance();

        // We simulate a wildcard type through a parameterized type or direct construction if possible
        // For simplicity in testing the method signature, we use a known complex type
        Type type = typeFactory.constructType(List.class).withGeneric(typeFactory.constructType(String.class)).getType();
        // Using a helper to get a type that involves wildcards if needed, 
        // but standard classes are sufficient to cover the branch logic of the wrapper.

        JavaType result = typeFactory.constructType(type, Integer.class);

        Assert.assertNotNull(result);
    }

    /**
     * Helper class to simulate ParameterizedType for testing purposes.
     */
    private static class ParameterizedTypeImpl implements ParameterizedType {
        private final Class<?> rawType;
        private final Type[] actualTypeArguments;

        public ParameterizedTypeImpl(Class<?> rawType, Type[] actualTypeArguments) {
            this.rawType = rawType;
            this.actualTypeArguments = actualTypeArguments;
        }

        @Override
        public Type[] getActualTypeArguments() {
            return actualTypeArguments;
        }

        @Override
        public Type getRawType() {
            return rawType;
        }

        @Override
        public Type getOwnerType() {
            return null;
        }
    }
}
